from pathlib import Pathfrom PIL import ImageALLOWED_EXTENSIONS = {".jpg", ".jpeg", ".png", ".webp"}MAX_SIZE = 1280def validate_image(image_path):    image_path = Path(image_path)    if not image_path.exists():        return False, f"La imagen no existe: {image_path}"    if not image_path.is_file():        return False, f"La ruta no corresponde a un archivo: {image_path}"    if image_path.suffix.lower() not in ALLOWED_EXTENSIONS:        return False, (            "Formato de imagen no compatible. "            "Usa JPG, JPEG, PNG o WEBP."        )    return True, ""def prepare_image(image_path):    image_path = Path(image_path)    with Image.open(image_path) as image:        if max(image.size) <= MAX_SIZE:            return image_path        output_path = image_path.with_name(            f"{image_path.stem}_small.jpg"        )        if output_path.exists():            return output_path        image.thumbnail((MAX_SIZE, MAX_SIZE))        image.convert("RGB").save(            output_path,            "JPEG",            quality=85        )    return output_path